#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""tools/netsurf_gen_svgtiny_colors.py - ★ v0.12.5：手写替身，替掉 libsvgtiny 的 **gperf** 步骤

libsvgtiny 的官方 Makefile：
    src/autogenerated_colors.c: src/colors.gperf
            gperf --output-file=$@.tmp $<
            sed -e 's/^\\(const struct svgtiny_named_color\\)/static \\1/' $@.tmp >$@

**本机没有 gperf**，所以 `svgtiny_parse.c` 会报 `'autogenerated_colors.c' file not found`。

生成规则（与 gperf 的输出语义一致）：
  * 读 `src/colors.gperf` 关键字段（`%%` 之后）每行 `<名字>, svgtiny_RGB(r, g, b)`；
  * `struct svgtiny_named_color` 定义在 **include/svgtiny.h**（不在这里重复定义）；
  * 生成 `static const struct svgtiny_named_color wordlist[]`；
  * 生成 `svgtiny_color_lookup(const char *s, size_t len)`：**大小写敏感**（.gperf 里没有
    %ignore-case）、**按长度精确匹配**（%compare-lengths），命中返回表项指针，否则 NULL；
    `svgtiny_parse.c` 用 `named_color->color` 取值。

如实记录：线性查找（147 个颜色名），每次解析一个 fill/stroke 属性调用一次，非热路径；
行为与 gperf 版一致，性能略低（可忽略）。

用法：
  py -3 tools/netsurf_gen_svgtiny_colors.py            # 写 third_party 里那份（构建脚本调它）
  py -3 tools/netsurf_gen_svgtiny_colors.py --check    # 只校验条目数
退出码：0 = 成功；2 = 输入缺失/解析不出条目。
"""
import argparse
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
SVG = os.path.join(ROOT, "third_party", "netsurf", "libsvgtiny")

LINE_RE = re.compile(r'^("?)([^",\s]+)\1\s*,\s*(svgtiny_RGB\s*\([^)]*\))\s*$')


def parse_gperf(path):
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        lines = f.read().splitlines()
    try:
        i = next(k for k, ln in enumerate(lines) if ln.strip() == "%%")
    except StopIteration:
        raise SystemExit("colors.gperf 里找不到 %%%% 分隔行：%s" % path)
    out = []
    for ln in lines[i + 1:]:
        s = ln.strip()
        if not s or s.startswith("#") or s == "%%":
            continue
        m = LINE_RE.match(s)
        if m:
            out.append((m.group(2), re.sub(r"\s+", " ", m.group(3))))
    if not out:
        raise SystemExit("colors.gperf 关键字段里一个条目都没解析出来：%s" % path)
    return out


def render(entries):
    L = []
    L.append("/*")
    L.append(" * autogenerated_colors.c —— **手写替身**（本机没有 gperf）")
    L.append(" *")
    L.append(" * 生成者：tools/netsurf_gen_svgtiny_colors.py（读 src/colors.gperf）")
    L.append(" * gperf 语义等价物：%compare-lengths -> 按长度精确匹配；无 %ignore-case -> 大小写敏感。")
    L.append(" * struct svgtiny_named_color 定义在 include/svgtiny.h，这里不重复定义。")
    L.append(" */")
    L.append("")
    L.append("#include <string.h>")
    L.append("")
    L.append("#include \"svgtiny.h\"")
    L.append("#include \"svgtiny_internal.h\"")
    L.append("")
    L.append("static const struct svgtiny_named_color wordlist[] = {")
    for name, rgb in entries:
        L.append("\t{ \"%s\", %s }," % (name, rgb))
    L.append("};")
    L.append("")
    L.append("#define SVGTINY_COLOR_WORDLIST_LEN (sizeof(wordlist) / sizeof(wordlist[0]))")
    L.append("")
    L.append("static const struct svgtiny_named_color *svgtiny_color_lookup(")
    L.append("\t\tconst char *str, size_t len)")
    L.append("{")
    L.append("\tsize_t i;")
    L.append("\tif (str == NULL) return NULL;")
    L.append("\tfor (i = 0; i < SVGTINY_COLOR_WORDLIST_LEN; i++) {")
    L.append("\t\tconst char *n = wordlist[i].name;")
    L.append("\t\tif (strlen(n) != len) continue;\t\t/* %compare-lengths */")
    L.append("\t\tif (strncmp(str, n, len) == 0) return &wordlist[i];")
    L.append("\t}")
    L.append("\treturn NULL;")
    L.append("}")
    L.append("")
    return "\n".join(L)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--gperf", default=os.path.join(SVG, "src", "colors.gperf"))
    ap.add_argument("--out", default=os.path.join(SVG, "src", "autogenerated_colors.c"))
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()
    if not os.path.exists(args.gperf):
        sys.stderr.write("[SVG-COLORS] FAIL 缺输入：%s\n" % args.gperf)
        return 2
    entries = parse_gperf(args.gperf)
    text = render(entries)
    if args.check:
        print("[SVG-COLORS] check ok=1 entries=%d" % len(entries))
        return 0
    with open(args.out, "wb") as f:
        f.write(text.encode("utf-8"))
    print("[SVG-COLORS] ok=1 entries=%d bytes=%d -> %s"
          % (len(entries), len(text.encode("utf-8")), args.out))
    return 0


if __name__ == "__main__":
    sys.exit(main())
